bool ProviderAgent::start(const AgentRequest& request)
{
    if (!ready() || m_busy)
        return false;
    m_pending_call_id.clear();
    m_pending_tool.clear();
    m_queued_calls.clear();
    m_step_skills.clear();
    m_results = RecordItem{RecordItem::Kind::Results};
    m_failed_call.clear();
    m_waiting_for_tool = false;
    m_rejected_calls   = 0;
    m_paused_turns     = 0;
