            std::cout << "HARNESS NOTE " << label << " current project " << persistence().document().project_id() << ":";
            for (const auto& match : matches)
                std::cout << ' ' << match.id << (match.current ? " current" : "") << " changed="
                          << (match.changed ? (*match.changed ? "yes" : "no") : "unknown");
