        json wrong = served;
        wrong[field] = field.back() == "kind" ? json(7) : json("480");
        CHECK_FALSE(account_reply_readable(wrong));
    }
    json expiry = served;
    expiry["credits"]["lots"][0]["expires_at"] = 1764547200;
